<script setup lang="ts">
import { formatDisplayDate } from '../../utils/formatDisplayDate'
definePageMeta({layout:'consumer'})
interface Point {date:string;value:number;reportId:string;referenceRange:string|null}
interface Observation {reportId:string;originalValue:string;originalUnit:string|null;date:string|null;referenceRange:string|null;notPlottedReason:string|null;reviewState:string}
interface Series {parameterName:string;testId:string;unit?:string;dataPoints:Point[];observations:Observation[];unplottedCount:number}
const {profileId,request,requireSession}=useConsumer(),route=useRoute();const series=ref<Series|null>(null),loading=ref(true),error=ref('')
useHead({title:'Test detail | Doclyzer'})
async function load(){const id=profileId.value;series.value=null;loading.value=true;error.value='';if(!id){loading.value=false;return}try{const data=await request<{parameters:Series[]}>(`/reports/lab-trends?profileId=${encodeURIComponent(id)}&parameterName=${encodeURIComponent(String(route.params.name))}`);if(id===profileId.value)series.value=data.parameters.find(p=>p.unit===(route.query.unit||undefined))??data.parameters[0]??null}catch(cause){error.value=(cause as Error).message}finally{loading.value=false}}
onMounted(async()=>{if(await requireSession())await load()});watch(profileId,()=>void load())
const sorted=computed(()=>[...(series.value?.observations??[])].sort((a,b)=>(b.date??'').localeCompare(a.date??'')))
const latest=computed(()=>sorted.value[0])
const chart=computed(()=>{const points=series.value?.dataPoints??[];if(points.length<2)return '';const times=points.map(p=>Date.parse(p.date));const values=points.map(p=>p.value);const minT=Math.min(...times),maxT=Math.max(...times),minV=Math.min(...values),maxV=Math.max(...values);return points.map((p,i)=>`${i?'L':'M'} ${40+(times[i]-minT)/(maxT-minT||1)*520} ${185-(values[i]-minV)/(maxV-minV||1)*140}`).join(' ')})
</script>
<template><div><NuxtLink to="/trends">← Trends</NuxtLink><p v-if="loading" role="status">Loading test…</p><p v-if="error" role="alert" class="alert error">{{ error }}</p><div v-if="series"><header class="page-heading"><div><p class="eyebrow">Test history</p><h1>{{ series.parameterName }}</h1><p class="muted">{{ series.unit??'Unit not recorded' }}</p></div></header><section class="card"><h2>Latest observation</h2><p v-if="latest" class="value">{{ latest.originalValue }} {{ latest.originalUnit }}</p><p>{{ latest?.date ? `Collected ${formatDisplayDate(latest.date)}` : 'Collection date unknown' }}</p><p>{{ latest?.referenceRange ? `Lab reference range: ${latest.referenceRange}` : 'Lab reference range unavailable. Comparison is unknown.' }}</p><p class="muted">A lab range comparison does not diagnose a condition.</p></section><section class="card"><h2>History</h2><p v-if="series.dataPoints.length===0">No observations can be charted yet.</p><p v-else-if="series.dataPoints.length===1">One dated numeric result. A trend needs at least two.</p><svg v-else viewBox="0 0 600 220" role="img" :aria-label="`Chart of ${series.parameterName}; the observation list below provides exact values and dates`"><path :d="chart" fill="none" stroke="#286d55" stroke-width="3" /><circle v-for="(p,i) in series.dataPoints" :key="i" :cx="40+(Date.parse(p.date)-Math.min(...series.dataPoints.map(x=>Date.parse(x.date))))/(Math.max(...series.dataPoints.map(x=>Date.parse(x.date)))-Math.min(...series.dataPoints.map(x=>Date.parse(x.date)))||1)*520" :cy="185-(p.value-Math.min(...series.dataPoints.map(x=>x.value)))/(Math.max(...series.dataPoints.map(x=>x.value))-Math.min(...series.dataPoints.map(x=>x.value))||1)*140" r="5" fill="#286d55" /></svg><p v-if="series.unplottedCount" class="muted">{{ series.unplottedCount }} observation{{ series.unplottedCount===1?'':'s' }} cannot be plotted because a date or exact numeric value is missing.</p><div v-for="(o,i) in sorted" :key="i" class="row observation"><div><strong>{{ o.originalValue }} {{ o.originalUnit }}</strong><p>{{ o.date ? formatDisplayDate(o.date) : 'Date unknown' }} · {{ o.referenceRange ? `Range ${o.referenceRange}` : 'Range unknown' }}</p><p v-if="o.notPlottedReason" class="muted">Not charted: {{ o.notPlottedReason.replaceAll('_',' ') }}</p></div><NuxtLink :to="`/reports/${o.reportId}`">Source report</NuxtLink></div></section><section class="card"><h2>About this test</h2><p>Reviewed education is not available for this test yet. Discuss interpretation with a qualified clinician, especially if you have symptoms or questions about your result.</p></section></div></div></template>
<style scoped>.value{font-size:2.3rem;font-weight:800;margin:5px 0}.observation{border-top:1px solid #e1e8e0;padding:13px 0}.observation p{margin:4px 0}svg{width:100%;height:auto;max-height:250px}</style>
